#include "Layout.h"
int main(int argc,char**argv){using namespace gpuls;try{require(argc==2,"GpuStructuredMemory output-directory");Context c;std::ostringstream o;o<<"{\"device\":"<<c.json()<<",\"allocations\":[";bool first=true;for(unsigned count:{0u,1u,10u,100u,2839u}){size_t inputBytes=count?size_t(count)*67904:256*1024,workBytes=count?size_t(count)*44256:128*1024;Engine e(c,inputBytes,workBytes);auto size=[&](ID3D12Resource* r){auto d=r->GetDesc();return c.device->GetResourceAllocationInfo(0,1,&d).SizeInBytes;};if(!first)o<<',';first=false;o<<"{\"systems\":"<<count<<",\"kind\":\""<<(count?"batch":"single-case capacity")<<"\",\"inputLogical\":"<<e.input.resource->GetDesc().Width<<",\"scratchLogical\":"<<e.work.resource->GetDesc().Width<<",\"inputCommitted\":"<<size(e.input.resource.Get())<<",\"scratchCommitted\":"<<size(e.work.resource.Get())<<",\"uploadCommitted\":"<<size(e.upload.Get())<<",\"readbackCommitted\":"<<size(e.readback.Get())<<",\"timestampReadbackCommitted\":"<<size(e.ticks.Get())<<'}';}o<<"]}";text(fs::path(argv[1])/"memory.json",o.str());c.audit();return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
